{
  "title": "Registration form (UI contract between participant and frontend)",
  "description": "Accessible names, roles and element ids the frontend renders; component, acceptance and end-to-end tests locate elements only through these. Texts are English. The frontend calls only GET /api/form-config and POST /api/registrations on its own origin (AR-01).",
  "page": {
    "url": "/",
    "heading": { "role": "heading", "level": 1, "name": "Conference registration" },
    "loading": { "text": "Loading…", "shownWhile": "GET /api/form-config is pending" },
    "configLoadError": { "role": "alert", "id": "general-error", "text": "The registration form could not be loaded. Please try again later." }
  },
  "typeChooser": {
    "role": "radiogroup",
    "name": "Registration type",
    "radios": [
      { "label": "External participant", "value": "EXTERNAL" },
      { "label": "Student", "value": "STUDENT" }
    ],
    "initial": "none selected; no fields, options, consents or submit button are shown until a type is chosen"
  },
  "fields": {
    "EXTERNAL": [
      { "name": "firstName", "label": "First name" },
      { "name": "lastName", "label": "Last name" },
      { "name": "email", "label": "Email", "inputType": "email" },
      { "name": "organization", "label": "Organization / institution" }
    ],
    "STUDENT": [
      { "name": "firstName", "label": "First name" },
      { "name": "lastName", "label": "Last name" },
      { "name": "email", "label": "Email", "inputType": "email" },
      { "name": "studyInstitution", "label": "Study institution" },
      { "name": "studyProgramme", "label": "Study programme" },
      { "name": "studentId", "label": "Student ID" }
    ],
    "rule": "exactly the fields of the chosen type are rendered as textboxes with these labels and name attributes; values typed into firstName, lastName and email are kept when the type changes"
  },
  "options": {
    "groups": [
      { "category": "WORKSHOP", "legend": "Workshops" },
      { "category": "EVENT", "legend": "Events" },
      { "category": "MEAL", "legend": "Meals" },
      { "category": "OTHER", "legend": "Other activities" }
    ],
    "rule": "one fieldset (role group) per category in this order, legend as above; each option of the form configuration whose availableTo contains the chosen type is a checkbox labelled with the option name and value = option id; a group with no such option is not rendered; all unchecked initially",
    "errorId": "options-error"
  },
  "consents": {
    "legend": "Consents",
    "rule": "one checkbox per consent of the form configuration, labelled with its text, value = consent id, never preselected (BR-05)",
    "errorId": "consents-error"
  },
  "captcha": {
    "testMode": { "when": "captchaTestMode = true", "checkbox": "I am not a robot (test mode)", "token": "test-pass when checked" },
    "production": { "when": "captchaTestMode = false", "widget": "Google reCAPTCHA v2 checkbox rendered into the element with id 'recaptcha' using captchaSiteKey; reset after every failed submission" },
