  for (const organizer of organizerEmails()) {
    const mails = await awaitMailsTo(organizer, p.email);
    expect(mails).toHaveLength(1);
    expect(await jsonAttachments(mails[0])).toEqual([copy]);
  }
});

import { expect, test } from "@playwright/test";
import {
  consentAndCaptcha,
  expectConfirmation,
  fillFields,
  openForm,
  selectOnePerCategory,
  shownOptions,
  submit,
  type Participant,
} from "./support/form";
import {
  awaitMailsTo,
  jsonAttachments,
  jsonCopy,
  organizerEmails,
  registrationsByEmail,
} from "./support/stack";

const CATEGORY_LEGEND: Record<string, string> = {
  WORKSHOP: "Workshops",
  EVENT: "Events",
  MEAL: "Meals",
  OTHER: "Other activities",
};

test("E2E-02 student registers (AC-002-01, AC-002-07, AC-004-01)", async ({ page, request }) => {
  const p: Participant = {
    firstName: "Nika",
    lastName: "Zupan",
    email: `e2e-student.${Date.now()}@example.org`,
    studyInstitution: "Univerza v Ljubljani",
    studyProgramme: "Informatika",
    studentId: "63220002",
  };
  const config = (await (await request.get("/api/form-config")).json()) as {
    options: { id: string; category: string; availableTo: string[] }[];
  };
  const expected: Record<string, string[]> = {};
  for (const o of config.options.filter((o) => o.availableTo.includes("STUDENT"))) {
    (expected[CATEGORY_LEGEND[o.category]] ??= []).push(o.id);
  }
  Object.values(expected).forEach((ids) => ids.sort());
  expect(config.options.some((o) => !o.availableTo.includes("STUDENT"))).toBe(true);

  await openForm(page, "Student");
  await expect(page.getByRole("textbox", { name: "Student ID" })).toBeVisible();
  await expect(page.getByRole("textbox", { name: "Study institution" })).toBeVisible();
  await expect(page.getByRole("textbox", { name: "Study programme" })).toBeVisible();
  await expect(page.getByRole("textbox", { name: "Organization / institution" })).toHaveCount(0);
  expect(await shownOptions(page)).toEqual(expected);
  await fillFields(page, p);
  await selectOnePerCategory(page);
  await consentAndCaptcha(page);
  await submit(page);

  await expectConfirmation(page, p);

  const rows = registrationsByEmail(p.email);
  expect(rows).toHaveLength(1);
  expect(rows[0]).toMatchObject({
    type: "STUDENT",
    firstName: p.firstName,
    lastName: p.lastName,
    studyInstitution: p.studyInstitution,
    studyProgramme: p.studyProgramme,
    studentId: p.studentId,
    organization: "",
  });
  const copy = jsonCopy(rows[0].id);
  expect(copy).toMatchObject({ id: rows[0].id, type: "STUDENT", studentId: p.studentId });

  expect(await awaitMailsTo(p.email)).toHaveLength(1);
  for (const organizer of organizerEmails()) {
    const mails = await awaitMailsTo(organizer, p.email);
    expect(mails).toHaveLength(1);
    expect(await jsonAttachments(mails[0])).toEqual([copy]);
  }
});

import { expect, test } from "@playwright/test";
import { consentAndCaptcha, fillFields, openForm, submit } from "./support/form";
import { registrationsByEmail, uniqueEmail } from "./support/stack";

test("E2E-03 field errors are shown next to the fields (AC-004-02, AC-004-03)", async ({ page }) => {
  const email = uniqueEmail("e2e-errors");
  const posts: string[] = [];
  page.on("request", (r) => {
    if (r.method() === "POST" && r.url().endsWith("/api/registrations")) posts.push(r.url());
  });

  await openForm(page, "Student");
  await fillFields(page, {
    firstName: "",
    lastName: "Horvat",
    email: "not-an-email@",
    studyInstitution: "Univerza v Mariboru",
    studyProgramme: "Elektrotehnika",
    studentId: "93210003",
  });
  await consentAndCaptcha(page);
  await submit(page);

  await expect(page.locator("#firstName-error")).toHaveText("This field is required.");
  await expect(page.locator("#email-error")).toHaveText("Enter a valid email address.");
  expect(posts).toHaveLength(0);

  await page.getByRole("textbox", { name: "First name" }).fill("Maja");
  await page.getByRole("textbox", { name: "Email" }).fill(email);
  await page.route("**/api/registrations", async (route) => {
    const body = JSON.parse(route.request().postData() ?? "{}") as { options?: string[] };
    body.options = [...(body.options ?? []), "e2e-unavailable-option"];
    await route.continue({ postData: JSON.stringify(body) });
  });
  const answer = page.waitForResponse((r) => r.url().endsWith("/api/registrations"));
  await submit(page);
  expect((await answer).status()).toBe(400);

  await expect(page.locator("#options-error")).not.toBeEmpty();
  await expect(page.getByRole("status")).toHaveCount(0);
  await expect(page.getByRole("textbox", { name: "First name" })).toHaveValue("Maja");
  await expect(page.getByRole("textbox", { name: "Last name" })).toHaveValue("Horvat");
  await expect(page.getByRole("textbox", { name: "Email" })).toHaveValue(email);
  await expect(page.getByRole("textbox", { name: "Student ID" })).toHaveValue("93210003");
  expect(posts).toHaveLength(1);
  expect(registrationsByEmail(email)).toHaveLength(0);
});

import { expect, test } from "@playwright/test";
import {
  consentAndCaptcha,
  expectConfirmation,
  fillFields,
  openForm,
  submit,
  type Participant,
} from "./support/form";
import {
  BACKEND_URL,
