package si.konferenca.registration.application;

import java.util.List;
import si.konferenca.registration.domain.ConferenceCatalog;
import si.konferenca.registration.domain.ConferenceOption;
import si.konferenca.registration.domain.ConsentDefinition;

/** What the registration form needs: active options, consents and the captcha settings. */
public class FormConfiguration {

  /** The form configuration as offered to participants (AC-003-01). */
  public record View(
      List<ConferenceOption> options,
      List<ConsentDefinition> consents,
      String captchaSiteKey,
      boolean captchaTestMode) {}

  private final ConferenceCatalog catalog;
  private final String captchaSiteKey;
  private final boolean captchaTestMode;

  public FormConfiguration(
      ConferenceCatalog catalog, String captchaSiteKey, boolean captchaTestMode) {
    this.catalog = catalog;
    this.captchaSiteKey = captchaSiteKey == null ? "" : captchaSiteKey;
    this.captchaTestMode = captchaTestMode;
  }

  public View current() {
    return new View(
        catalog.activeOptions(), catalog.consents(), captchaSiteKey, captchaTestMode);
  }
}

package si.konferenca.registration.web;

import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import si.konferenca.registration.application.FormConfiguration;
import si.konferenca.registration.domain.ConferenceOption;
import si.konferenca.registration.domain.RegistrationType;

/** {@code GET /api/form-config} (public). */
@RestController
public class FormConfigController {

  /** One active option. */
  public record OptionResponse(String id, String name, String category, List<String> availableTo) {}

  /** One consent with its wording. */
  public record ConsentResponse(String id, String text, boolean mandatory) {}

  /** The response body of {@code openapi.json} FormConfig. */
  public record FormConfigResponse(
      List<OptionResponse> options,
      List<ConsentResponse> consents,
      String captchaSiteKey,
      boolean captchaTestMode) {}

  private final FormConfiguration formConfiguration;

  public FormConfigController(FormConfiguration formConfiguration) {
    this.formConfiguration = formConfiguration;
  }

  @GetMapping("/api/form-config")
  public FormConfigResponse formConfig() {
    FormConfiguration.View view = formConfiguration.current();
    return new FormConfigResponse(
        view.options().stream().map(FormConfigController::option).toList(),
        view.consents().stream()
            .map(c -> new ConsentResponse(c.id(), c.text(), c.mandatory()))
            .toList(),
        view.captchaSiteKey(),
        view.captchaTestMode());
  }

  private static OptionResponse option(ConferenceOption option) {
    List<String> types =
        List.of(RegistrationType.values()).stream()
            .filter(option::isAvailableTo)
            .map(Enum::name)
            .toList();
    return new OptionResponse(option.id(), option.name(), option.category().name(), types);
  }
}

package si.konferenca.registration.config;

import java.util.List;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter.ReferrerPolicy;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

/**
 * Public form and registration endpoints, HTTP Basic for the organizer export, security headers
 * (SB-02, SB-03, SB-10, BR-08).
 */
@Configuration
public class SecurityConfig {

  static final String ORGANIZER = "ORGANIZER";

  @Bean
  public SecurityFilterChain apiSecurity(HttpSecurity http, AppProperties properties)
      throws Exception {
    http.csrf(AbstractHttpConfigurer::disable)
        .formLogin(AbstractHttpConfigurer::disable)
        .logout(AbstractHttpConfigurer::disable)
        .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .httpBasic(basic -> basic.realmName("organizer"))
        .headers(
            headers ->
                headers
                    .contentSecurityPolicy(
                        csp -> csp.policyDirectives("default-src 'none'; frame-ancestors 'none'"))
                    .frameOptions(frame -> frame.deny())
                    .referrerPolicy(referrer -> referrer.policy(ReferrerPolicy.NO_REFERRER)))
        .authorizeHttpRequests(
            requests ->
                requests
                    .requestMatchers(HttpMethod.GET, "/api/form-config")
                    .permitAll()
                    .requestMatchers(HttpMethod.POST, "/api/registrations")
                    .permitAll()
                    .requestMatchers(HttpMethod.GET, "/actuator/health", "/actuator/health/**")
                    .permitAll()
                    .requestMatchers("/error")
                    .permitAll()
                    .requestMatchers(HttpMethod.GET, "/api/export")
                    .hasRole(ORGANIZER)
                    .anyRequest()
                    .denyAll());
    String origin = properties.cors().allowedOrigin();
    if (origin != null && !origin.isBlank()) {
      CorsConfiguration cors = new CorsConfiguration();
      cors.setAllowedOrigins(List.of(origin));
      cors.setAllowedMethods(List.of("GET", "POST"));
      cors.setAllowedHeaders(List.of("Content-Type", "Authorization"));
      UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
      source.registerCorsConfiguration("/api/**", cors);
      http.cors(c -> c.configurationSource(source));
    }
    return http.build();
  }

  @Bean
  public PasswordEncoder passwordEncoder() {
    return new BCryptPasswordEncoder();
  }

  /** The one organizer account; only the BCrypt hash of the password is kept (SB-03). */
  @Bean
  public UserDetailsService organizerAccount(AppProperties properties, PasswordEncoder encoder) {
    AppProperties.Organizer organizer = properties.organizer();
    return new InMemoryUserDetailsManager(
        User.withUsername(organizer.username())
            .password(encoder.encode(organizer.password()))
            .roles(ORGANIZER)
            .build());
  }
}

