import { CATEGORIES, type FormOption } from "../domain/types";

interface Props {
  options: FormOption[];
  selected: string[];
  error?: string;
  onToggle: (id: string) => void;
}

/** One fieldset per category with options, in the order of `CATEGORIES` (BR-04). */
export function OptionGroups({ options, selected, error, onToggle }: Props) {
  return (
    <div className="options">
      {CATEGORIES.map(({ category, legend }) => {
        const inCategory = options.filter((o) => o.category === category);
        if (inCategory.length === 0) return null;
        return (
          <fieldset key={category} aria-describedby={error ? "options-error" : undefined}>
            <legend>{legend}</legend>
            {inCategory.map((option) => (
              <label key={option.id} className="choice">
                <input
                  type="checkbox"
                  name="options"
                  value={option.id}
                  checked={selected.includes(option.id)}
                  onChange={() => onToggle(option.id)}
                />
                {option.name}
              </label>
            ))}
          </fieldset>
        );
      })}
      {error && (
        <span id="options-error" className="error">
          {error}
        </span>
      )}
    </div>
  );
}

import { useEffect, useRef } from "react";

export const TEST_TOKEN = "test-pass";
const SCRIPT_ID = "recaptcha-script";
const SCRIPT_URL = "https://www.google.com/recaptcha/api.js?render=explicit&onload=onRecaptchaLoad";

interface Grecaptcha {
  render: (
    element: HTMLElement,
    options: { sitekey: string; callback: (token: string) => void; "expired-callback": () => void },
  ) => number;
  reset: (widget: number) => void;
}

declare global {
  interface Window {
    grecaptcha?: Grecaptcha;
    onRecaptchaLoad?: () => void;
  }
}

interface Props {
  testMode: boolean;
  siteKey: string;
  token: string;
  /** Changes after every failed submission, so the production widget asks again. */
  resetCount: number;
  error?: string;
  onToken: (token: string) => void;
}

/** The test-mode check or the Google reCAPTCHA v2 widget (SR-01, AR-07). */
export function Captcha({ testMode, siteKey, token, resetCount, error, onToken }: Props) {
  return (
    <div className="captcha">
      {testMode ? (
        <label className="choice">
          <input
            type="checkbox"
            checked={token === TEST_TOKEN}
            onChange={(e) => onToken(e.target.checked ? TEST_TOKEN : "")}
            aria-describedby={error ? "captchaToken-error" : undefined}
          />
          I am not a robot (test mode)
        </label>
      ) : (
        <GoogleWidget siteKey={siteKey} resetCount={resetCount} onToken={onToken} />
      )}
      {error && (
        <span id="captchaToken-error" className="error">
          {error}
        </span>
      )}
    </div>
  );
}

function GoogleWidget({
  siteKey,
  resetCount,
  onToken,
}: {
  siteKey: string;
  resetCount: number;
  onToken: (token: string) => void;
}) {
  const container = useRef<HTMLDivElement>(null);
  const widget = useRef<number | null>(null);
  const callback = useRef(onToken);
  callback.current = onToken;

  useEffect(() => {
    const render = () => {
      if (container.current && window.grecaptcha && widget.current === null) {
        widget.current = window.grecaptcha.render(container.current, {
          sitekey: siteKey,
          callback: (t) => callback.current(t),
          "expired-callback": () => callback.current(""),
        });
      }
    };
    if (window.grecaptcha) {
      render();
    } else {
      window.onRecaptchaLoad = render;
      if (!document.getElementById(SCRIPT_ID)) {
        const script = document.createElement("script");
        script.id = SCRIPT_ID;
        script.src = SCRIPT_URL;
        script.async = true;
        script.defer = true;
        document.head.appendChild(script);
      }
    }
  }, [siteKey]);

  useEffect(() => {
    if (resetCount > 0 && widget.current !== null && window.grecaptcha) {
      window.grecaptcha.reset(widget.current);
      callback.current("");
    }
  }, [resetCount]);

  return <div id="recaptcha" ref={container} />;
}

import { useState, type FormEvent } from "react";
import { submitRegistration } from "../api/client";
import { buildPayload } from "../domain/payload";
import {
  EMPTY_VALUES,
  FIELDS,
  optionsFor,
  type FormConfig,
  type FormValues,
  type RegistrationType,
  type TextField,
} from "../domain/types";
import { validate } from "../domain/validation";
import { Captcha } from "./Captcha";
import { OptionGroups } from "./OptionGroups";

/** What the confirmation shows after HTTP 201. */
export interface Registered {
  firstName: string;
  lastName: string;
  optionNames: string[];
}

interface Props {
  config: FormConfig;
  onRegistered: (registered: Registered) => void;
}

const TYPES: { value: RegistrationType; label: string }[] = [
  { value: "EXTERNAL", label: "External participant" },
  { value: "STUDENT", label: "Student" },
];

function toggle(list: string[], id: string): string[] {
  return list.includes(id) ? list.filter((x) => x !== id) : [...list, id];
}

/** The registration form of `ui-registration-form.json`. */
export function RegistrationForm({ config, onRegistered }: Props) {
  const [values, setValues] = useState<FormValues>(EMPTY_VALUES);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [submitting, setSubmitting] = useState(false);
  const [captchaResets, setCaptchaResets] = useState(0);

  const type = values.type;
  const available = type === "" ? [] : optionsFor(config, type);

  const chooseType = (next: RegistrationType) => {
    const offered = optionsFor(config, next).map((o) => o.id);
    setValues((v) => ({ ...v, type: next, options: v.options.filter((id) => offered.includes(id)) }));
  };

  const setText = (field: TextField, value: string) =>
    setValues((v) => ({ ...v, text: { ...v.text, [field]: value } }));

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (type === "" || submitting) return;
    const found = validate(values, config);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    setSubmitting(true);
    const result = await submitRegistration(buildPayload({ ...values, type }, config));
    setSubmitting(false);
    if (result.kind === "created") {
      onRegistered({
        firstName: values.text.firstName.trim(),
        lastName: values.text.lastName.trim(),
        optionNames: available.filter((o) => values.options.includes(o.id)).map((o) => o.name),
      });
      return;
    }
    setCaptchaResets((n) => n + 1);
  };

  return (
    <form noValidate onSubmit={submit}>
      <div role="radiogroup" aria-labelledby="type-label" className="types">
        <span id="type-label" className="group-label">
          Registration type
        </span>
        {TYPES.map((t) => (
          <label key={t.value} className="choice">
            <input
              type="radio"
              name="type"
              value={t.value}
              checked={type === t.value}
              onChange={() => chooseType(t.value)}
            />
            {t.label}
          </label>
        ))}
      </div>

      {type !== "" && (
        <>
          {FIELDS[type].map((field) => (
            <div key={field.name} className="field">
              <label htmlFor={`field-${field.name}`}>{field.label}</label>
              <input
                id={`field-${field.name}`}
                name={field.name}
                type={field.inputType}
                value={values.text[field.name]}
                onChange={(e) => setText(field.name, e.target.value)}
                aria-invalid={errors[field.name] ? "true" : undefined}
                aria-describedby={errors[field.name] ? `${field.name}-error` : undefined}
              />
              {errors[field.name] && (
                <span id={`${field.name}-error`} className="error">
                  {errors[field.name]}
                </span>
              )}
            </div>
          ))}

          <OptionGroups
            options={available}
            selected={values.options}
            error={errors.options}
            onToggle={(id) => setValues((v) => ({ ...v, options: toggle(v.options, id) }))}
          />

          <fieldset className="consents" aria-describedby={errors.consents ? "consents-error" : undefined}>
            <legend>Consents</legend>
            {config.consents.map((consent) => (
              <label key={consent.id} className="choice">
                <input
                  type="checkbox"
                  name="consents"
                  value={consent.id}
                  checked={values.consents.includes(consent.id)}
                  onChange={() => setValues((v) => ({ ...v, consents: toggle(v.consents, consent.id) }))}
                />
                {consent.text}
              </label>
            ))}
            {errors.consents && (
              <span id="consents-error" className="error">
                {errors.consents}
              </span>
            )}
          </fieldset>

          <Captcha
            testMode={config.captchaTestMode}
            siteKey={config.captchaSiteKey}
            token={values.captchaToken}
            resetCount={captchaResets}
            error={errors.captchaToken}
            onToken={(token) => setValues((v) => ({ ...v, captchaToken: token }))}
          />

          <button type="submit" disabled={submitting}>
            Register
          </button>
        </>
      )}
    </form>
  );
}

