    ConferenceOption b = catalog.option("b").orElseThrow();
    assertThat(b.active()).isFalse();
    assertThat(b.availableTo()).containsExactly(RegistrationType.STUDENT);
    assertThat(catalog.consents()).hasSize(2);
    assertThat(catalog.consent("privacy").orElseThrow().mandatory()).isTrue();
    assertThat(catalog.consent("photos").orElseThrow().mandatory()).isFalse();
  }

  @Test
  void rejectsAnUnknownCategoryNamingIt() {
    assertThatThrownBy(() -> load(config("{\"id\": \"a\", \"name\": \"A\", \"category\": \"SPORT\"}", CONSENT)))
        .isInstanceOf(ConferenceConfigException.class)
        .hasMessage("Option 'a' has the unknown category 'SPORT'");
  }

  @Test
  void rejectsAMissingCategory() {
    assertThatThrownBy(() -> load(config("{\"id\": \"a\", \"name\": \"A\"}", CONSENT)))
        .hasMessage("Option 'a' has no category");
  }

  @Test
  void rejectsAnUnknownRegistrationType() {
    assertThatThrownBy(
            () ->
                load(
                    config(
                        "{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\","
                            + " \"availableTo\": [\"GUEST\"]}",
                        CONSENT)))
        .hasMessage("Option 'a' names an unknown registration type \"GUEST\"");
    assertThatThrownBy(
            () ->
                load(
                    config(
                        "{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\","
                            + " \"availableTo\": [1]}",
                        CONSENT)))
        .hasMessageStartingWith("Option 'a' names an unknown registration type");
  }

  @Test
  void rejectsAnEmptyAvailability() {
    assertThatThrownBy(
            () ->
                load(
                    config(
                        "{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"availableTo\": []}",
                        CONSENT)))
        .hasMessage("Option 'a' is available to no registration type");
  }

  @ParameterizedTest
  @CsvSource(
      delimiter = '|',
      value = {
        "{\"options\": [], \"consents\": [], \"extra\": 1}|Unknown field 'extra' in the configuration",
        "[]|Expected an object for the configuration",
        "{\"consents\": []}|Field 'options' must be an array",
        "{\"options\": {}, \"consents\": []}|Field 'options' must be an array",
        "{\"options\": [1], \"consents\": []}|Expected an object for an option",
        "{\"options\": [], \"consents\": [\"x\"]}|Expected an object for a consent",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"price\": 3}],"
            + " \"consents\": []}|Unknown field 'price' in an option",
        "{\"options\": [{\"id\": 7, \"name\": \"A\", \"category\": \"MEAL\"}], \"consents\": []}"
            + "|Field 'id' must be a string",
        "{\"options\": [{\"id\": \"a\", \"name\": \"A\", \"category\": \"MEAL\", \"active\": \"yes\"}],"
            + " \"consents\": []}|Field 'active' must be true or false",
        "{\"options\": [], \"consents\": [{\"id\": \"c\", \"text\": \"T\"}]}"
            + "|Field 'mandatory' must be true or false",
        "{\"options\": [], \"consents\": [{\"id\": \"c\", \"text\": \"T\", \"mandatory\": true,"
            + " \"x\": 1}]}|Unknown field 'x' in a consent",
        "{\"options\": [{\"id\": \"a\", \"name\": null, \"category\": \"MEAL\"}], \"consents\": []}"
            + "|Missing name of option 'a'"
      })
  void rejectsMalformedConfigurations(String json, String message) {
    assertThatThrownBy(() -> load(json))
        .isInstanceOf(ConferenceConfigException.class)
        .hasMessage(message);
  }

  @Test
  void rejectsUnreadableJson() {
    assertThatThrownBy(() -> load("{ not json"))
        .isInstanceOf(ConferenceConfigException.class)
        .hasMessage("Conference configuration test is unreadable")
        .hasCauseInstanceOf(RuntimeException.class);
  }
}

package si.konferenca.registration.adapter.jsoncopy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import si.konferenca.registration.domain.GivenConsent;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;

class FileJsonCopyStoreTest {

  @TempDir Path dir;

  private static Registration registration() {
    Instant at = Instant.parse("2026-10-21T11:30:00.123Z");
    return new Registration(
        UUID.fromString("0b6f4a8e-1c2d-4e5f-8a9b-0c1d2e3f4a5b"),
        RegistrationType.STUDENT,
        "Žiga",
        "Čeh",
        "ziga@example.org",
        null,
        "UL",
        "CS",
        "6321",
        List.of("ws-ai", "meal-lunch"),
        List.of(new GivenConsent("privacy", at)),
        at);
  }

  @Test
  void writesTheCopyNamedAfterTheIdAndReturnsItsBytes() throws IOException {
    Path copies = dir.resolve("nested/copies");
    FileJsonCopyStore store = new FileJsonCopyStore(copies);

    byte[] written = store.save(registration());

    Path file = copies.resolve("0b6f4a8e-1c2d-4e5f-8a9b-0c1d2e3f4a5b.json");
    assertThat(file).exists();
    assertThat(Files.readAllBytes(file)).isEqualTo(written);
    assertThat(new String(written, StandardCharsets.UTF_8))
        .isEqualTo(
            "{\"id\":\"0b6f4a8e-1c2d-4e5f-8a9b-0c1d2e3f4a5b\",\"type\":\"STUDENT\","
                + "\"firstName\":\"Žiga\",\"lastName\":\"Čeh\",\"email\":\"ziga@example.org\","
                + "\"organization\":null,\"studyInstitution\":\"UL\",\"studyProgramme\":\"CS\","
                + "\"studentId\":\"6321\",\"options\":[\"ws-ai\",\"meal-lunch\"],"
                + "\"consents\":[{\"id\":\"privacy\",\"givenAt\":\"2026-10-21T11:30:00.123Z\"}],"
                + "\"registeredAt\":\"2026-10-21T11:30:00.123Z\"}");
    try (Stream<Path> files = Files.list(copies)) {
      assertThat(files).containsExactly(file);
    }
  }

  @Test
  void discardRemovesTheCopyAndIgnoresAMissingOne() {
    FileJsonCopyStore store = new FileJsonCopyStore(dir);
    Registration r = registration();
    store.save(r);

    store.discard(r.id());

    assertThat(dir.resolve(r.id() + ".json")).doesNotExist();
    assertThatCode(() -> store.discard(r.id())).doesNotThrowAnyException();
  }

  @Test
  void discardThatCannotDeleteOnlyLogs() throws IOException {
    Registration r = registration();
    Path blocking = Files.createDirectories(dir.resolve(r.id() + ".json"));
    Files.writeString(blocking.resolve("inside.txt"), "x");

    assertThatCode(() -> new FileJsonCopyStore(dir).discard(r.id())).doesNotThrowAnyException();
    assertThat(blocking).exists();
  }

  @Test
  void failsWhenTheDirectoryCannotBeCreated() throws IOException {
    Path file = Files.writeString(dir.resolve("plain-file"), "x");

    assertThatThrownBy(() -> new FileJsonCopyStore(file.resolve("copies")).save(registration()))
        .isInstanceOf(UncheckedIOException.class)
        .hasMessage("JSON copy could not be written");
  }
}

package si.konferenca.registration.adapter.captcha;

import static org.assertj.core.api.Assertions.assertThat;

import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

class GoogleCaptchaVerifierTest {

  private HttpServer server;
  private final AtomicInteger status = new AtomicInteger(200);
  private final AtomicReference<String> answer = new AtomicReference<>("{\"success\": true}");
  private final AtomicReference<String> received = new AtomicReference<>();

  @BeforeEach
  void start() throws IOException {
    server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    server.createContext(
        "/verify",
        exchange -> {
          received.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
          byte[] body = answer.get().getBytes(StandardCharsets.UTF_8);
          exchange.getResponseHeaders().add("Content-Type", "application/json");
          exchange.sendResponseHeaders(status.get(), body.length == 0 ? -1 : body.length);
          if (body.length > 0) {
            exchange.getResponseBody().write(body);
          }
          exchange.close();
        });
    server.start();
  }

  @AfterEach
  void stop() {
    server.stop(0);
  }

  private GoogleCaptchaVerifier verifier() {
    return new GoogleCaptchaVerifier(
        "http://127.0.0.1:" + server.getAddress().getPort() + "/verify", "the secret");
  }

  @Test
  void acceptsSuccessTrueAndPostsSecretAndToken() {
    assertThat(verifier().verify("tok en")).isTrue();
    assertThat(received.get()).isEqualTo("secret=the+secret&response=tok+en");
  }

  @ParameterizedTest
  @ValueSource(
      strings = {
        "{\"success\": false, \"error-codes\": [\"invalid-input-response\"]}",
        "{\"success\": \"true\"}",
        "{}",
        "not json",
        ""
      })
  void rejectsEveryOtherAnswer(String body) {
    answer.set(body);

    assertThat(verifier().verify("token")).isFalse();
  }

  @Test
  void rejectsAnErrorStatus() {
    status.set(500);

    assertThat(verifier().verify("token")).isFalse();
  }

  @Test
  void rejectsWhenTheEndpointCannotBeReached() throws IOException {
    int closed;
    try (ServerSocket socket = new ServerSocket(0)) {
      closed = socket.getLocalPort();
    }

    assertThat(new GoogleCaptchaVerifier("http://127.0.0.1:" + closed + "/v", "s").verify("t"))
        .isFalse();
  }

  @Test
  void testModeAcceptsOnlyTheTestToken() {
    TestModeCaptchaVerifier testMode = new TestModeCaptchaVerifier();

    assertThat(testMode.verify("test-pass")).isTrue();
    assertThat(testMode.verify("test-pass ")).isFalse();
    assertThat(testMode.verify(null)).isFalse();
  }
}

